sys_ux_client_script.script:
function handler({ api, event, helpers, imports }) {
	const mergePARFiltersV2 = imports["global.mergePARFilters"]().v2;
	const { appliedFilters } = event.payload;
	api.setState("parFilters2", ({ currentValue, api }) => {
		const { parFilters2, teste2 } = mergePARFiltersV2(
			currentValue,
			appliedFilters
		);
		api.setState("teste2", teste2);
		return parFilters2;
	});
}
